import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { attendanceService } from '../../services/attendanceService';
import '../../styles/table.scss';

// --- Utils ---
const statusClass = (status) => {
  if (status === 'Có mặt' || status === 'Đi làm' || status === 'Present') return 'status-green';
  if (status === 'Vắng mặt' || status === 'Absent') return 'status-red';
  if (status === 'Nghỉ phép' || status === 'Leave') return 'status-blue';
  if (status === 'Đi muộn' || status === 'Về sớm' || status === 'Trễ') return 'status-orange';
  return 'status-gray';
};

const getStatusText = (status) => {
  if (status === 'Present') return 'Có mặt';
  if (status === 'Absent') return 'Vắng mặt';
  if (status === 'Leave') return 'Nghỉ phép';
  return status;
}

const getInitials = (name) => {
  if (!name) return 'NV';
  return name.split(' ').map((w) => w[0]).slice(-2).join('').toUpperCase();
};

const getReferenceDate = (monthStr) => {
  return `${monthStr}-01`;
};

// --- Main Component ---
export default function AttendanceList() {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  const [selectedMonth, setSelectedMonth] = useState('2024-09');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedDepartment, setSelectedDepartment] = useState('ALL');

  const [summaryData, setSummaryData] = useState([]);
  const [todayData, setTodayData] = useState([]);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const [todayPage, setTodayPage] = useState(1);

  const availableMonths = [
    { value: '2024-09', label: 'Tháng 9, 2024' },
    { value: '2026-04', label: 'Tháng 4, 2026' },
    { value: '2026-05', label: 'Tháng 5, 2026' },
  ];

  // Fetch Data
  useEffect(() => {
    fetchSummary();
  }, [selectedMonth]);

  useEffect(() => {
    fetchToday();
  }, [selectedDate]);

  const fetchSummary = async () => {
    setIsLoading(true);
    try {
      const res = await attendanceService.getSummary(selectedMonth);
      if (res.success) {
        setSummaryData(res.data || []);
      }
    } catch (e) {
      setErrorMessage('Không thể tải danh sách nhân viên');
    }
    setIsLoading(false);
  };

  const fetchToday = async () => {
    try {
      const res = await attendanceService.getTodayAttendance(selectedDate);
      if (res.success) {
        setTodayData(res.data || []);
      }
    } catch (e) {
      // ignore today errors
    }
  };

  // Processing Data
  const departmentOptions = useMemo(() => {
    const depts = new Set(summaryData.map(d => d.DepartmentName).filter(Boolean));
    return Array.from(depts);
  }, [summaryData]);

  const filteredSummary = useMemo(() => {
    if (selectedDepartment === 'ALL') return summaryData;
    return summaryData.filter(d => d.DepartmentName === selectedDepartment);
  }, [summaryData, selectedDepartment]);

  // Main Table Pagination
  const PAGE_SIZE = 10;
  const totalEntries = filteredSummary.length;
  const totalPages = Math.max(Math.ceil(totalEntries / PAGE_SIZE), 1);
  const safePage = Math.min(currentPage, totalPages);
  const startIndex = (safePage - 1) * PAGE_SIZE;
  const endIndex = Math.min(startIndex + PAGE_SIZE, totalEntries);
  const pagedAttendanceRows = filteredSummary.slice(startIndex, endIndex);

  // Today Table Pagination
  const TODAY_PAGE_SIZE = 5;
  const todayTotal = todayData.length;
  const todayTotalPages = Math.max(Math.ceil(todayTotal / TODAY_PAGE_SIZE), 1);
  const todaySafePage = Math.min(todayPage, todayTotalPages);
  const todayStartIdx = (todaySafePage - 1) * TODAY_PAGE_SIZE;
  const todayEndIdx = Math.min(todayStartIdx + TODAY_PAGE_SIZE, todayTotal);
  const pagedTodayRows = todayData.slice(todayStartIdx, todayEndIdx);

  // Stats
  const presentCount = summaryData.reduce((acc, curr) => acc + (curr.PresentDays > 0 ? 1 : 0), 0);
  const absentCount = summaryData.reduce((acc, curr) => acc + (curr.AbsentDays > 0 ? 1 : 0), 0);
  const leaveCount = summaryData.reduce((acc, curr) => acc + (curr.LeaveDays > 0 ? 1 : 0), 0);
  const holidayCount = 0;

  const totalWorkDays = summaryData.reduce((acc, curr) => acc + (curr.PresentDays || 0), 0);
  const totalWorkHours = totalWorkDays * 8;

  const generateCalendarDays = () => {
    const [year, month] = selectedMonth.split('-');
    const daysInMonth = new Date(year, month, 0).getDate();
    let days = [];
    for (let i = 1; i <= 3; i++) days.push({ day: 31 - 3 + i, muted: true }); // Mock prev month
    for (let i = 1; i <= daysInMonth; i++) {
      days.push({ day: i, date: `${year}-${month}-${String(i).padStart(2, '0')}`, muted: false });
    }
    return days;
  };

  const calendarDays = generateCalendarDays();

  return (
    <div className="attendance-app animate-fade-in">
      {errorMessage && <div style={{ padding: '1rem', backgroundColor: '#fee2e2', color: '#ef4444', margin: '1rem 24px', borderRadius: '8px' }}>{errorMessage}</div>}
      <div className="content-inner">
        {/* ── Bộ lọc ── */}
        <section className="filter-row">
          <input type="text" placeholder="Tìm kiếm nhân viên theo tên, mã số hoặc phòng ban..." readOnly />
          <select
            value={selectedMonth}
            onChange={(e) => {
              const newMonth = e.target.value;
              setSelectedMonth(newMonth);
              setSelectedDate(getReferenceDate(newMonth));
              setCurrentPage(1);
            }}
          >
            {availableMonths.map((m) => (
              <option key={m.value} value={m.value}>{m.label}</option>
            ))}
          </select>
          <div className="department-filter">
            <select
              value={selectedDepartment}
              onChange={(e) => { setSelectedDepartment(e.target.value); setCurrentPage(1); }}
            >
              <option value="ALL">Tất cả phòng ban</option>
              {departmentOptions.map((name) => (
                <option key={name} value={name}>{name}</option>
              ))}
            </select>
          </div>
          <button type="button" className="primary" onClick={() => navigate('/alerts/anniversary')}>
            Thông báo kỉ niệm ngày làm việc
          </button>
        </section>

        {/* ── Thẻ thống kê ── */}
        <section className="stats-grid">
          <article className="stat-card">
            <div className="report-card-head"><span className="metric-icon" style={{background: '#dbeafe', color: '#1d4ed8'}}>👥</span><span className="metric-up">+2.4%</span></div>
            <p>Tổng số nhân viên</p>
            <strong>{isLoading ? '...' : totalEntries.toLocaleString('vi-VN')}</strong>
          </article>
          <article className="stat-card">
            <div className="report-card-head"><span className="metric-icon" style={{background: '#dcfce7', color: '#15803d'}}>✅</span><span className="metric-up" style={{color: '#6b7280'}}>Tỷ lệ 94%</span></div>
            <p>Hiện tại</p>
            <strong>{isLoading ? '...' : presentCount.toLocaleString('vi-VN')}</strong>
          </article>
          <article className="stat-card">
            <div className="report-card-head"><span className="metric-icon" style={{background: '#fee2e2', color: '#b91c1c'}}>❌</span><span className="metric-down">-12 hôm nay</span></div>
            <p>Vắng mặt</p>
            <strong>{isLoading ? '...' : absentCount.toLocaleString('vi-VN')}</strong>
          </article>
          <article className="stat-card">
            <div className="report-card-head"><span className="metric-icon" style={{background: '#fef3c7', color: '#b45309'}}>⏰</span><span className="metric-up" style={{color: '#6b7280'}}>Trung bình 8.5m</span></div>
            <p>Muộn / Nghỉ</p>
            <strong>{isLoading ? '...' : leaveCount.toLocaleString('vi-VN')}</strong>
          </article>
        </section>

        {/* ── Bảng nhật ký chấm công ── */}
        <section className="panel">
          <div className="panel-head table-head">
            <div className="table-title-wrap">
              <h3>Nhật ký chấm công nhân viên</h3>
              <span>Hiển thị {Math.max(endIndex, 0)} trong số {totalEntries.toLocaleString('vi-VN')}</span>
            </div>
            <div className="table-actions">
              <button type="button" className="icon-btn" onClick={() => {fetchSummary(); fetchToday();}}>↻</button>
              <button type="button" className="icon-btn">⋮</button>
            </div>
          </div>
          <div className="table-wrap">
            <table className="attendance-table">
              <thead>
                <tr>
                  <th><input type="checkbox" /></th>
                  <th>Mã nhân viên</th>
                  <th>Họ và tên / Liên hệ</th>
                  <th>Số điện thoại</th>
                  <th>Phòng ban</th>
                  <th>Chức vụ</th>
                  <th>Ngày vào làm</th>
                  <th>Ngày sinh</th>
                  <th>Địa chỉ</th>
                  <th>Tình trạng</th>
                </tr>
              </thead>
              <tbody>
                {pagedAttendanceRows.length === 0 ? (
                  <tr>
                    <td colSpan="10" style={{ textAlign: 'center', padding: '24px', color: '#8b95ac' }}>Không có dữ liệu</td>
                  </tr>
                ) : pagedAttendanceRows.map((row) => (
                  <tr key={row.EmployeeID}>
                    <td><input type="checkbox" /></td>
                    <td><span className="employee-code">EMP-{String(row.EmployeeID).padStart(5, '0')}</span></td>
                    <td>
                      <div className="employee-cell">
                        <div className="employee-avatar">{getInitials(row.FullName)}</div>
                        <div className="employee-info">
                          <strong>{row.FullName}</strong>
                          <small>{row.Email || '-'}</small>
                        </div>
                      </div>
                    </td>
                    <td>{row.PhoneNumber || '-'}</td>
                    <td>{row.DepartmentName || '-'}</td>
                    <td>{row.PositionName || '-'}</td>
                    <td>{row.HireDate || '-'}</td>
                    <td>{row.DateOfBirth || '-'}</td>
                    <td>-</td>
                    <td>
                      <span className={`status-pill ${statusClass(row.PresentDays > 0 ? 'Có mặt' : row.AbsentDays > 0 ? 'Vắng mặt' : 'Nghỉ phép')}`}>
                        {row.PresentDays > 0 ? 'Có mặt' : row.AbsentDays > 0 ? 'Vắng mặt' : 'Nghỉ phép'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="table-footer">
            <span>
              Showing {totalEntries === 0 ? 0 : startIndex + 1} to {endIndex} of {totalEntries.toLocaleString('vi-VN')} entries
            </span>
            <div className="pagination">
              <button className="page-btn" onClick={() => setCurrentPage(p => Math.max(p - 1, 1))} disabled={safePage === 1}>‹</button>
              {Array.from({length: Math.min(totalPages, 5)}).map((_, i) => (
                <span key={i} className="page-slot">
                  <button className={`page-btn ${safePage === i + 1 ? 'active' : ''}`} onClick={() => setCurrentPage(i + 1)}>{i + 1}</button>
                </span>
              ))}
              <button className="page-btn" onClick={() => setCurrentPage(p => Math.min(p + 1, totalPages))} disabled={safePage === totalPages}>›</button>
            </div>
          </div>
        </section>

        {/* ── Lịch + Bảng hôm nay ── */}
        <section className="two-panels">
          {/* Lịch */}
          <article className="panel calendar" style={{ border: 'none', borderRadius: 0, margin: 0, padding: '18px 24px' }}>
            <h3>Lịch</h3>
            <div className="calendar-box">
              <div className="calendar-top">
                <button type="button" className="calendar-nav">‹</button>
                <span>{availableMonths.find(m => m.value === selectedMonth)?.label || selectedMonth}</span>
                <button type="button" className="calendar-nav">›</button>
              </div>
              <div className="calendar-weekdays">
                {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'Cn'].map((d) => (
                  <span key={d} className="weekday-cell">{d}</span>
                ))}
              </div>
              <div className="calendar-days">
                {calendarDays.map((item, idx) => (
                  <span
                    key={`${item.day}-${idx}`}
                    className={`day-cell ${item.date === selectedDate ? 'selected-day' : ''} ${item.muted ? 'muted-day' : ''}`}
                    onClick={() => { if (!item.muted && item.date) setSelectedDate(item.date); }}
                    style={{ cursor: item.muted ? 'default' : 'pointer' }}
                  >
                    {item.day}
                  </span>
                ))}
              </div>
            </div>
            <div className="calendar-legend">
              {[
                { cls: 'dot-green', label: 'Đi làm đầy đủ' },
                { cls: 'dot-yellow', label: 'Đi muộn' },
                { cls: 'dot-red', label: 'Vắng mặt' },
                { cls: 'dot-blue', label: 'Nghỉ phép' },
              ].map(({ cls, label }) => (
                <div key={cls}><span className={`dot ${cls}`} />{label}</div>
              ))}
            </div>
          </article>

          {/* Bảng hôm nay */}
          <article className="panel today-panel">
            <div className="today-head">
              <h3>Bảng chấm công ngày {selectedDate.split('-').reverse().join('/')}</h3>
              <span className="month-badge">{availableMonths.find(m => m.value === selectedMonth)?.label || selectedMonth}</span>
            </div>
            <div className="today-table">
              <div className="today-row today-row-head">
                <span>Nhân viên</span><span>Vào</span><span>Ra</span><span>Giờ làm</span><span>Trạng thái</span>
              </div>
              {pagedTodayRows.length === 0 ? (
                <div style={{ padding: '16px 8px', color: '#8b95ac', fontSize: '13px', textAlign: 'center' }}>
                  {isLoading ? 'Đang tải...' : 'Không có dữ liệu hôm nay'}
                </div>
              ) : pagedTodayRows.map((item, idx) => (
                <div key={`${item.EmployeeID}-${idx}`} className="today-row">
                  <span style={{ fontWeight: 500 }}>{item.FullName}</span>
                  <span style={{ color: '#1572df' }}>08:00</span>
                  <span style={{ color: '#1572df' }}>17:00</span>
                  <span>{item.WorkHours} h</span>
                  <span><span className={`status-pill ${statusClass(getStatusText(item.Status))}`}>{getStatusText(item.Status)}</span></span>
                </div>
              ))}
            </div>
            <div className="today-footer">
              <span className="today-footer-info">
                Hiển thị {todayTotal === 0 ? 0 : todayStartIdx + 1}-{todayEndIdx} trong số {todayTotal} nhân viên
              </span>
              <div className="pagination">
                <button className="page-btn" onClick={() => setTodayPage(p => Math.max(p - 1, 1))} disabled={todaySafePage === 1}>‹</button>
                {Array.from({length: Math.min(todayTotalPages, 3)}).map((_, i) => (
                  <span key={i} className="page-slot">
                    <button className={`page-btn ${todaySafePage === i + 1 ? 'active' : ''}`} onClick={() => setTodayPage(i + 1)}>{i + 1}</button>
                  </span>
                ))}
                <button className="page-btn" onClick={() => setTodayPage(p => Math.min(p + 1, todayTotalPages))} disabled={todaySafePage === todayTotalPages}>›</button>
              </div>
            </div>
            <button type="button" className="outline-btn report-btn" onClick={() => navigate('/reports')}>
              Tạo báo cáo chi tiết
            </button>
          </article>
        </section>

        {/* ── Tóm tắt tháng ── */}
        <section className="panel summary">
          <h3 className="summary-title">Tổng hợp tháng này</h3>
          <div className="summary-grid">
            <div className="summary-item">
              <p>Tổng ngày làm việc</p>
              <strong>{totalWorkDays}</strong>
            </div>
            <div className="summary-item">
              <p>Trung bình đi làm</p>
              <strong>93.5%</strong>
            </div>
            <div className="summary-item">
              <p>Tổng giờ làm</p>
              <strong>{totalWorkHours}h</strong>
            </div>
            <div className="summary-item">
              <p>Tổng giờ tăng ca</p>
              <strong>124h</strong>
            </div>
          </div>
        </section>

      </div>
    </div>
  );
}
